// board (optional): the player's poured board, {image, look} from Board Studio. The match paths are drawn over it,
// with the same square tints and softening the player saw while playing.
export function matchArtwork(moves, board) {
  const tint=(t,i)=>`<rect x="${80+i%8*70}" y="${80+Math.floor(i/8)*70}" width="70" height="70" fill="rgb(${t.rgb.join(',')})" opacity="${t.a}"/>`;
  const point=s=>[115+(s.charCodeAt(0)-97)*70,605-(Number(s[1])-1)*70];
  const lines=moves.map((m,i)=>{const [x,y]=point(m.from),[xx,yy]=point(m.to);const bow=(i%2?1:-1)*(35+i%5*8);return `<path d="M${x},${y} Q${(x+xx)/2+bow},${(y+yy)/2-bow} ${xx},${yy}" fill="none" stroke="${m.color==='w'?'#dfc090':'#965c51'}" stroke-width="${m.captured?8:4}" stroke-linecap="round" opacity=".75"/><circle cx="${xx}" cy="${yy}" r="${m.captured?9:4}" fill="${m.color==='w'?'#dfc090':'#965c51'}"/>`;}).join('');
  return `<svg xmlns="http://www.w3.org/2000/svg" width="720" height="720" viewBox="0 0 720 720"><rect width="720" height="720" fill="#342b29"/><rect x="28" y="28" width="664" height="664" fill="none" stroke="#d1b990" stroke-width="2"/><rect x="43" y="43" width="634" height="634" fill="none" stroke="#8d7461"/>${board?`<defs><filter id="soften"><feColorMatrix type="saturate" values="${board.look.saturate}"/></filter></defs><image href="${board.image}" x="80" y="80" width="560" height="560" preserveAspectRatio="none" filter="url(#soften)"/>${Array.from({length:64},(_,i)=>tint((Math.floor(i/8)+i%8)%2?board.look.dark:board.look.light,i)).join('')}`:Array.from({length:64},(_,i)=>{const x=97+i%8*70,y=97+Math.floor(i/8)*70;return `<rect x="${x}" y="${y}" width="35" height="35" fill="${(Math.floor(i/8)+i%8)%2?'#4b3a32':'#3a302c'}"/><circle cx="${x+18}" cy="${y+18}" r="1.5" fill="#a68a65" opacity=".4"/>`;}).join('')}${moves.length?lines:'<path d="M220 510 Q520 440 360 220 Q180 350 500 430" stroke="#d7b789" stroke-width="4" fill="none" opacity=".65"/>'}<text x="360" y="82" text-anchor="middle" fill="#d1b990" font-family="Georgia,serif" font-size="15" letter-spacing="6">CHESS ATELIER</text><text x="360" y="654" text-anchor="middle" fill="#b69b80" font-family="Georgia,serif" font-size="12" letter-spacing="3">${moves.length?moves.length+' MOVES / A MATCH, REMEMBERED':'THE FIRST MOVE IS YOURS'}</text></svg>`;
}
